text:
Componente client-side para Next.js. Bloquea incluso el scroll de iOS, conserva la posición, compensa la scrollbar, cierra con `Escape`, atrapa el foco y lo devuelve al botón.

```tsx
"use client";

import Link from "next/link";
import { useEffect, useRef, useState } from "react";

const links = [
  { href: "/", label: "Inicio" },
  { href: "/proyectos", label: "Proyectos" },
  { href: "/estudio", label: "Estudio" },
  { href: "/contacto", label: "Contacto" },
];

export function MobileMenu() {
  const [isOpen, setIsOpen] = useState(false);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!isOpen) return;

    const scrollY = window.scrollY;
    const scrollbarWidth =
      window.innerWidth - document.documentElement.clientWidth;

    const previousBodyStyles = {
      overflow: document.body.style.overflow,
      position: document.body.style.position,
      top: document.body.style.top,
      width: document.body.style.width,
      paddingRight: document.body.style.paddingRight,
    };

    Object.assign(document.body.style, {
      overflow: "hidden",
      position: "fixed",
      top: `-${scrollY}px`,
      width: "100%",
      paddingRight: scrollbarWidth ? `${scrollbarWidth}px` : "",
    });

    const focusableElements = Array.from(
      menuRef.current?.querySelectorAll<HTMLElement>(
        'a[href], button:not([disabled]), [tabindex]:not([tabindex="-1"])',
      ) ?? [],
    );

    requestAnimationFrame(() => focusableElements[0]?.focus());

    function handleKeyDown(event: KeyboardEvent) {
      if (event.key === "Escape") {
        setIsOpen(false);
        return;
      }

      if (event.key !== "Tab" || focusableElements.length === 0) return;

      const firstElement = focusableElements[0];
      const lastElement = focusableElements[focusableElements.length - 1];

      if (event.shiftKey && document.activeElement === firstElement) {
        event.preventDefault();
        lastElement.focus();
      } else if (!event.shiftKey && document.activeElement === lastElement) {
        event.preventDefault();
        firstElement.focus();
      }
    }

    document.addEventListener("keydown", handleKeyDown);

    return () => {
      document.removeEventListener("keydown", handleKeyDown);
      Object.assign(document.body.style, previousBodyStyles);

      window.scrollTo({ top: scrollY, behavior: "instant" });
      triggerRef.current?.focus();
    };
  }, [isOpen]);

  function closeMenu() {
    setIsOpen(false);
  }

  return (
    <header className="relative z-50 flex items-center justify-between px-5 py-5 md:px-8">
      <Link
        href="/"
        className="relative z-[60] text-sm font-semibold uppercase tracking-[0.2em]"
        onClick={closeMenu}
      >
        Estudio
      </Link>

      <button
        ref={triggerRef}
        type="button"
        aria-label={isOpen ? "Cerrar menú" : "Abrir menú"}
        aria-expanded={isOpen}
        aria-controls="mobile-navigation"
        onClick={() => setIsOpen((current) => !current)}
        className="relative z-[60] grid size-12 place-items-center rounded-full border border-current/20 transition-colors hover:bg-black hover:text-white focus-visible:outline-2 focus-visible:outline-offset-4 focus-visible:outline-current md:hidden"
      >
        <span className="sr-only">
          {isOpen ? "Cerrar menú" : "Abrir menú"}
        </span>

        <span className="relative block h-4 w-5" aria-hidden="true">
          <span
            className={[
              "absolute left-0 top-1 block h-px w-5 bg-current",
              "transition-transform duration-500 ease-[cubic-bezier(.76,0,.24,1)]",
              isOpen ? "translate-y-1 rotate-45" : "",
            ].join(" ")}
          />
          <span
            className={[
              "absolute bottom-1 left-0 block h-px w-5 bg-current",
              "transition-transform duration-500 ease-[cubic-bezier(.76,0,.24,1)]",
              isOpen ? "-translate-y-1 -rotate-45" : "",
            ].join(" ")}
          />
        </span>
      </button>

      <div
        id="mobile-navigation"
        ref={menuRef}
        role="dialog"
        aria-modal="true"
        aria-label="Navegación principal"
        aria-hidden={!isOpen}
        inert={!isOpen}
        className={[
          "fixed inset-0 z-50 flex min-h-dvh flex-col bg-[#e8ff3d] text-[#111]",
          "transition-[clip-path,visibility] duration-700",
          "ease-[cubic-bezier(.76,0,.24,1)] md:hidden",
          isOpen
            ? "visible [clip-path:inset(0_0_0_0)]"
            : "invisible [clip-path:inset(0_0_100%_0)]",
        ].join(" ")}
      >
        <nav className="flex flex-1 items-end px-5 pb-10 pt-28">
          <ul className="w-full">
            {links.map((link, index) => (
              <li
                key={link.href}
                className="border-b border-black/20 first:border-t"
              >
                <Link
                  href={link.href}
                  onClick={closeMenu}
                  className={[
                    "group flex items-center justify-between py-4",
                    "text-[clamp(2.8rem,15vw,5.5rem)] font-medium",
                    "leading-none tracking-[-0.07em]",
                    "focus-visible:outline-none focus-visible:pl-3",
                    "transition-[padding] duration-300",
                    isOpen
                      ? "translate-y-0 opacity-100"
                      : "translate-y-8 opacity-0",
                    "transition-[transform,opacity,padding] duration-500",
                  ].join(" ")}
                  style={{
                    transitionDelay: isOpen ? `${150 + index * 70}ms` : "0ms",
                  }}
                >
                  <span>{link.label}</span>
                  <span className="text-base tracking-normal transition-transform duration-300 group-hover:rotate-45">
                    ↗
                  </span>
                </Link>
              </li>
            ))}
          </ul>
        </nav>

        <div className="flex justify-between px-5 pb-6 text-xs uppercase tracking-[0.18em]">
          <span>Santiago, CL</span>
          <span>© {new Date().getFullYear()}</span>
        </div>
      </div>
    </header>
  );
}
```

`min-h-dvh` evita problemas con la barra dinámica del navegador móvil. El bloqueo mediante `position: fixed` es más fiable en Safari/iOS que usar solamente `overflow: hidden`.
